ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_DEFINE_CHARACTER = "Define un carácter personalizable para uso posterior. Argumentos: glyph (bytearray)   1-8 valores de 8 bits que definen una imagen de píxeles. Los datos se pasan por columnas, con el bit 0 en la parte inferior y el bit 7 en la parte superior. char_code (integer) ID del carácter. Código ASCII 0-31. Predeterminado: 0 Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_DRAW = "Vacía el búfer de pantalla actual al dispositivo por I2C (renderizar).";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_IS_SET = "Indica si un píxel está activado. Argumentos: x (int) Coordenada X de izquierda a derecha. y (int) Coordenada Y de abajo hacia arriba. Devuelve: Si el píxel está activado (True) o no (False)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_PLOT = "Dibuja un punto en la matriz. (0,0) es la esquina inferior izquierda vista desde el frente. Argumentos: x (integer)   Coordenada X (0 - 7) de izquierda a derecha. y (integer)   Coordenada Y (0 - 7) de abajo hacia arriba. ink (integer) Color del píxel: 1 = 'blanco', 0 = 'negro'. NOTA: el modo de vídeo inverso invierte esto. Predeterminado: 1. xor (bool)    Si un píxel subyacente ya del color ink debe invertirse. Predeterminado: False. Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_SCROLL_TEXT = "Desplaza la línea de texto especificada hacia la izquierda a través de la pantalla. Argumentos: the_line (string) La cadena a mostrar. speed (float)     El retardo entre fotogramas. Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_SET_ANGLE = "Ajusta la orientación de la matriz. Argumentos: angle (integer) Ángulo de autorrotación de la pantalla, de 0 a -360 grados. Predeterminado: 0 Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_SET_CHARACTER = "Muestra un único carácter especificado por su valor ASCII en la matriz. Argumentos: ascii_value (integer) Código ASCII del carácter. Predeterminado: 32 (espacio). centre (bool)         Si el icono debe mostrarse centrado en la pantalla. Predeterminado: False Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_SET_ICON = "Muestra un carácter personalizado en la matriz. Argumentos: glyph (array) 1-8 valores de 8 bits que definen una imagen de píxeles. Los datos se pasan como columnas 0 a 7, de izquierda a derecha. El bit 0 está abajo, el bit 7 arriba. centre (bool) Si el icono debe mostrarse centrado en la pantalla. Predeterminado: False Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX_SET_INVERSE = "Invierte el color de tinta de la pantalla. Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX__FILL = "Rellena el búfer, columna por columna, con el valor de byte especificado";
ACMsg.STM32_HT16K33MATRIX_HT16K33MATRIX__ROTATE_MATRIX = "Rota una matriz de 8 enteros por el ángulo especificado en incrementos de 90 grados: 0 = ninguno, 1 = 90 en el sentido de las agujas del reloj, 2 = 180, 3 = 90 en sentido antihorario";
ACMsg.STM32_HT16K33MATRIX_MODULE = "Controlador para el Adafruit 8x8 LED matrix monocroma (HT16K33). Incluye fuente de glifos, rotación, inversión y dibujo de píxeles.";
