ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_CHARACTER = "Muestra un carácter alfanumérico en el dígito especificado. Solo están disponibles los caracteres del conjunto de la clase; otros caracteres pueden definirse y mostrarse usando 'set_glyph()'. Este método actualiza el búfer de pantalla, pero no lo envía al dispositivo. Llame a 'update()' para renderizar el búfer en la pantalla. Argumentos: char (string):  El carácter a mostrar. digit (int):    El dígito donde mostrarlo. Predeterminado: 0 (dígito más a la izquierda). Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_CODE = "Muestra un carácter alfanumérico en el dígito especificado. Solo están disponibles los caracteres del conjunto de la clase; otros caracteres pueden definirse y mostrarse usando 'set_glyph()'. Este método actualiza el búfer de pantalla, pero no lo envía al dispositivo. Llame a 'update()' para renderizar el búfer en la pantalla. Argumentos: code (int):     El código específico de la clase para el carácter. digit (int):    El dígito donde mostrarlo. Predeterminado: 0 (dígito más a la izquierda). Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_GLYPH = "Coloca la matriz de carácter de entrada (un entero de 16 bits) en la fila especificada, añadiendo un punto decimal si se requiere. El valor de la matriz de caracteres se calcula activando los bit(s) que representan los segmentos que desea iluminar: 0                           9 _ 5 |   | 1           8 \\ | / 10 |   |                        \\|/ 6  - -  7 4 |   | 2              /|              | _ |                   13 / | \\ 11          . 14 3                           12 El bit 14 es el punto, pero esto se establece con el parámetro 3. Nota: el bit 15 no es leído por la pantalla. Argumentos: glyph (int):   El patrón del glifo. digit (int):   El dígito donde mostrar el glifo. Predeterminado: 0 (dígito más a la izquierda). Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_NUMBER = "Muestra un valor decimal único (0-9) en el dígito especificado. Este método actualiza el búfer de pantalla, pero no lo envía al dispositivo. Llame a 'update()' para renderizar el búfer en la pantalla. Argumentos: number (int):  El número a mostrar. digit (int):   El dígito donde mostrar el número. Predeterminado: 0 (dígito más a la izquierda). Devuelve: La instancia (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14__SET_DIGIT = "Método `_set_digit` de `HT16K33Segment14`.";
ACMsg.STM32_HT16K33SEGMENT14_MODULE = "Controlador para pantallas LED alfanuméricas de 14 segmentos controladas por HT16K33. Soporta glifos, números y códigos de segmentos.";
